// Gets the URL test data of the web-platform-tests (WPT), as released, at the
// commit that whatwg-url's own tests use (see README.md), and wraps each file
// in a script that assigns a global, for the JS tests (native/test/js).
// Run from this folder with Node (no dependencies): `node update.mjs`.

import { writeFileSync } from "node:fs";
import path from "node:path";

const COMMIT = "cfb4a4b0bb480522d095557b16d86a15d6897e35";
const BASE = `https://raw.githubusercontent.com/web-platform-tests/wpt/${COMMIT}/`;
const HERE = path.dirname(new URL(import.meta.url).pathname);

// The data file and the global the tests read it from.
const DATA = {
  "url/resources/urltestdata.json": "wptUrlTestData",
  "url/resources/urltestdata-javascript-only.json":
    "wptUrlTestDataJavaScriptOnly",
  "url/resources/setters_tests.json": "wptSettersTests",
  "url/resources/toascii.json": "wptToAsciiTests",
};

const get = async (file) => {
  const response = await fetch(BASE + file);
  if (!response.ok) throw new Error(`${file}: ${response.status}`);
  return response.text();
};

for (const [file, name] of Object.entries(DATA)) {
  const json = await get(file);
  JSON.parse(json);
  const out = `${path.basename(file, ".json").replaceAll("-", "_")}_data.js`;
  writeFileSync(
    path.join(HERE, out),
    `// Generated by update.mjs: do not edit. WPT ${file} at ${COMMIT}.\nglobalThis.${name} = ${json.trim()};\n`,
  );
  console.log(out);
}
writeFileSync(path.join(HERE, "LICENSE.md"), await get("LICENSE.md"));
